<?php
namespace App\Http\Controllers;use App\Models\{Insight,Survey,User};use App\Services\InsightEngineService;use Carbon\Carbon;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class InsightController extends Controller{public function index(Request $r):View{abort_unless($r->user()->can('dashboard.view'),403);$insights=Insight::with(['rule','floor.building','surveyArea','actions'])->latest('generated_at')->paginate(30);return view('insights.index',compact('insights'));}public function generate(Request $r,Survey $survey,InsightEngineService $engine):JsonResponse{abort_unless($r->user()->can('insights.review'),403);$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$to=isset($d['to'])?Carbon::parse($d['to']):now();$from=isset($d['from'])?Carbon::parse($d['from']):$to->copy()->subDays(7);return response()->json($engine->generateForSurvey($survey,$from,$to),201);}public function review(Request $r,Insight $insight):JsonResponse{abort_unless($r->user()->can('insights.review'),403);$d=$r->validate(['status'=>'required|in:reviewed,dismissed,investigating,resolved']);$insight->update(['status'=>$d['status'],'reviewed_at'=>now(),'reviewed_by'=>$r->user()->id,'resolved_at'=>$d['status']==='resolved'?now():null]);return response()->json($insight->refresh());}public function action(Request $r,Insight $insight):JsonResponse{abort_unless($r->user()->can('insights.review'),403);$d=$r->validate(['title'=>'required|string|max:180','description'=>'nullable|string|max:3000','assigned_to'=>'nullable|exists:users,id','due_date'=>'nullable|date']);$d['created_by']=$r->user()->id;return response()->json($insight->actions()->create($d),201);}}
